{"summary":"Validate CSV integrity and print preview via single Python command","security_risk":"LOW","command":"python3 -c "import os,csv,itertools; p='/root/security_audit.csv';
assert os.path.exists(p) and os.path.getsize(p)>0, 'missing_or_empty';
print('size_bytes', os.path.getsize(p));
expected=['Package','Version','CVE_ID','Severity','CVSS_Score','Fixed_Version','Title','Url'];
allowed={'HIGH','CRITICAL'}; req=['Package','Version','CVE_ID','Severity'];
with open(p,newline='',encoding='utf-8') as f:
 r=csv.reader(f); header=next(r);
assert header==expected, (header, expected);
print('header_ok');
with open(p,newline='',encoding='utf-8') as f:
 r=csv.DictReader(f); n=0
 for row in r:
  n+=1; s=(row.get('Severity') or '').strip().upper();
  assert s in allowed, s
  for k in req: assert (row.get(k) or '').strip(), (k,row)
print('rows_ok', n);
print('--- preview ---');
with open(p,'r',encoding='utf-8') as f:
 for line in itertools.islice(f, 20):
  print(line.rstrip('\n'))
""}

